// This code has been fully generated by an AI.

// Package weather adds the weather during an activity from Open-Meteo
// (https://open-meteo.com, free for non-commercial use, no API key).
//
// Only the start point rounded to 0.01° (≈ 1 km) and the dates leave the
// device. Results are stored per activity; failed lookups are retried later.
package weather

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"log/slog"
	"math"
	"net/http"
	"net/url"
	"strconv"
	"time"

	"github.com/stefanluchs/my-velo/internal/geo"
	"github.com/stefanluchs/my-velo/internal/store"
)

// Default endpoints. The forecast API also serves the last months and is
// more current than the reanalysis archive.
const (
	ArchiveURL  = "https://archive-api.open-meteo.com/v1/archive"
	ForecastURL = "https://api.open-meteo.com/v1/forecast"
	// recentDays selects the forecast API for activities younger than this.
	recentDays = 30
)

// ErrRateLimited means Open-Meteo asked to slow down; the batch stops and
// continues at the next interval without marking activities as failed.
var ErrRateLimited = errors.New("open-meteo rate limit")

// Client queries Open-Meteo.
type Client struct {
	HTTP        *http.Client
	ArchiveURL  string
	ForecastURL string
	Now         func() time.Time
}

// NewClient returns a client for the public Open-Meteo endpoints.
func NewClient() *Client {
	return &Client{HTTP: &http.Client{Timeout: 20 * time.Second}, ArchiveURL: ArchiveURL, ForecastURL: ForecastURL, Now: time.Now}
}

type response struct {
	Error  bool   `json:"error"`
	Reason string `json:"reason"`
	Hourly struct {
		Time     []string   `json:"time"`
		Temp     []*float64 `json:"temperature_2m"`
		Apparent []*float64 `json:"apparent_temperature"`
		Precip   []*float64 `json:"precipitation"`
		Code     []*float64 `json:"weather_code"`
		Wind     []*float64 `json:"wind_speed_10m"`
		WindDir  []*float64 `json:"wind_direction_10m"`
		Gust     []*float64 `json:"wind_gusts_10m"`
	} `json:"hourly"`
}

// Fetch returns the weather at lat/lon for the hours from start to
// start+duration (UTC).
func (c *Client) Fetch(ctx context.Context, lat, lon float64, start time.Time, duration time.Duration) (store.Weather, error) {
	start = start.UTC()
	end := start.Add(max(duration, 0))
	base := c.ArchiveURL
	if c.Now().Sub(start) < recentDays*24*time.Hour {
		base = c.ForecastURL
	}
	q := url.Values{
		"latitude":        {strconv.FormatFloat(round(lat, 2), 'f', 2, 64)},
		"longitude":       {strconv.FormatFloat(round(lon, 2), 'f', 2, 64)},
		"start_date":      {start.Format(time.DateOnly)},
		"end_date":        {end.Format(time.DateOnly)},
		"hourly":          {"temperature_2m,apparent_temperature,precipitation,weather_code,wind_speed_10m,wind_direction_10m,wind_gusts_10m"},
		"timezone":        {"GMT"},
		"wind_speed_unit": {"kmh"},
	}
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, base+"?"+q.Encode(), nil)
	if err != nil {
		return store.Weather{}, err
	}
	resp, err := c.HTTP.Do(req)
	if err != nil {
		return store.Weather{}, err
	}
	defer resp.Body.Close()
	if resp.StatusCode == http.StatusTooManyRequests {
		return store.Weather{}, ErrRateLimited
	}
	var r response
	if err := json.NewDecoder(io.LimitReader(resp.Body, 1<<20)).Decode(&r); err != nil {
		return store.Weather{}, fmt.Errorf("open-meteo: HTTP %d: %w", resp.StatusCode, err)
	}
	if r.Error || resp.StatusCode != http.StatusOK {
		return store.Weather{}, fmt.Errorf("open-meteo: HTTP %d: %s", resp.StatusCode, r.Reason)
	}
	return summarize(&r, start.Truncate(time.Hour), end)
}

// summarize aggregates the hours of the activity: temperature range,
// apparent temperature at the start, mean wind (direction as vector mean),
// strongest gust, precipitation sum and the most severe weather code.
func summarize(r *response, from, to time.Time) (store.Weather, error) {
	w := store.Weather{Status: store.WeatherOK, TempMinC: math.Inf(1), TempMaxC: math.Inf(-1)}
	var n, windSum, u, v float64
	apparentSet := false
	for i, ts := range r.Hourly.Time {
		t, err := time.Parse("2006-01-02T15:04", ts)
		if err != nil || t.Before(from) || t.After(to) {
			continue
		}
		temp := at(r.Hourly.Temp, i)
		if math.IsNaN(temp) {
			continue
		}
		n++
		w.TempMinC, w.TempMaxC = math.Min(w.TempMinC, temp), math.Max(w.TempMaxC, temp)
		if a := at(r.Hourly.Apparent, i); !apparentSet && !math.IsNaN(a) {
			w.ApparentC, apparentSet = a, true
		}
		if p := at(r.Hourly.Precip, i); !math.IsNaN(p) {
			w.PrecipMM += p
		}
		if c := at(r.Hourly.Code, i); !math.IsNaN(c) && int(c) > w.Code {
			w.Code = int(c)
		}
		if g := at(r.Hourly.Gust, i); !math.IsNaN(g) {
			w.GustKmh = math.Max(w.GustKmh, g)
		}
		if s, d := at(r.Hourly.Wind, i), at(r.Hourly.WindDir, i); !math.IsNaN(s) {
			windSum += s
			if !math.IsNaN(d) {
				rad := d * math.Pi / 180
				u, v = u+s*math.Sin(rad), v+s*math.Cos(rad)
			}
		}
	}
	if n == 0 {
		return store.Weather{}, errors.New("open-meteo: no data for the activity hours")
	}
	w.WindKmh = round(windSum/n, 1)
	w.WindDirDeg = math.Mod(math.Round(math.Atan2(u, v)*180/math.Pi)+360, 360)
	w.PrecipMM = round(w.PrecipMM, 1)
	return w, nil
}

func at(s []*float64, i int) float64 {
	if i < len(s) && s[i] != nil {
		return *s[i]
	}
	return math.NaN()
}

func round(v float64, decimals int) float64 {
	p := math.Pow(10, float64(decimals))
	return math.Round(v*p) / p
}

// Service fills in missing weather in the background.
type Service struct {
	Client *Client
	Store  *store.Store
	Logger *slog.Logger
	// Interval between checks for activities without weather.
	Interval time.Duration
	// Delay between two requests to stay well below the rate limits.
	Delay time.Duration
	// RetryAfter is the wait before a failed lookup is tried again.
	RetryAfter time.Duration
	// Batch limits the lookups per run.
	Batch int
}

// Run backfills after firstDelay and then every Interval until ctx ends.
func (s *Service) Run(ctx context.Context, firstDelay time.Duration) {
	timer := time.NewTimer(firstDelay)
	defer timer.Stop()
	for {
		select {
		case <-ctx.Done():
			return
		case <-timer.C:
		}
		n, err := s.Backfill(ctx)
		switch {
		case err != nil && !errors.Is(err, context.Canceled):
			s.logger().Warn("weather backfill", "fetched", n, "err", err)
		case n > 0:
			s.logger().Info("weather backfill", "fetched", n)
		}
		timer.Reset(s.Interval)
	}
}

// Backfill looks up the weather of up to Batch activities and returns how
// many were stored successfully.
func (s *Service) Backfill(ctx context.Context) (int, error) {
	tasks, err := s.Store.WeatherPending(ctx, s.RetryAfter, max(1, s.Batch))
	if err != nil {
		return 0, err
	}
	ok := 0
	for i, t := range tasks {
		if i > 0 && s.Delay > 0 {
			select {
			case <-ctx.Done():
				return ok, ctx.Err()
			case <-time.After(s.Delay):
			}
		}
		ls, err := geo.DecodePolyline(t.Polyline)
		if err != nil || len(ls) == 0 {
			continue
		}
		w, err := s.Client.Fetch(ctx, ls[0][1], ls[0][0], t.StartTime, time.Duration(t.ElapsedS*float64(time.Second)))
		if errors.Is(err, ErrRateLimited) || ctx.Err() != nil {
			return ok, err
		}
		if err != nil {
			s.logger().Debug("weather lookup failed", "activity", t.ActivityID, "err", err)
			w = store.Weather{Status: store.WeatherError, Error: err.Error()}
		} else {
			ok++
		}
		if err := s.Store.SaveWeather(ctx, t.ActivityID, w); err != nil {
			return ok, err
		}
	}
	return ok, nil
}

func (s *Service) logger() *slog.Logger {
	if s.Logger != nil {
		return s.Logger
	}
	return slog.New(slog.DiscardHandler)
}
